 "content": "def transform(grid):
    """Mark the smallest zero component with 7 and largest with 8."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            component = []
            while stack:
                y, x = stack.pop()
                component.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(component)
    if len(components) >= 2:
        smallest = min(components, key=len)
        largest = max(components, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8
    return out
